class Solution {
  public int maxDistinct(String s) {
    // cut right before the first occurrence of every letter
    boolean[] seen = new boolean[26];
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
      int c = s.charAt(i) - 'a';
      if (!seen[c]) {
        seen[c] = true;
        count++;
      }
    }
    return count;
  }
}
